require __DIR__.'/config.php'; require_login(); $title='Verification Document'; $result=null; $missing=[]; $err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$ref=trim((string)($_POST['ref_no']??''));$mobile=trim((string)($_POST['mobile']??''));if($ref===''&&$mobile==='')$err='Geli REF.NS ama mobile number.';else{$sql='SELECT full_name,mobile,ref_no,document_type,created_at FROM documents WHERE 1=1';$args=[];if($ref!==''){$sql.=' AND ref_no=?';$args[]=$ref;}if($mobile!==''){$sql.=' AND mobile=?';$args[]=$mobile;}if(($_SESSION['role']??'staff')!=='admin'){$sql.=' AND uploaded_by=?';$args[]=(int)$_SESSION['user_id'];}$sql.=' LIMIT 2';$st=$pdo->prepare($sql);$st->execute($args);$result=$st->fetchAll();}}
$rows=$pdo->query("SELECT ref_no FROM documents WHERE ref_no REGEXP '^NS/[0-9]+/[0-9]{4}$'")->fetchAll();$years=[];foreach($rows as $r){if(preg_match('~^NS/(\d+)/((?:19|20)\d{2})$~',$r['ref_no'],$m))$years[$m[2]][(int)$m[1]]=true;}foreach($years as $yr=>$nums){$min=min(array_keys($nums));$max=max(array_keys($nums));for($i=$min;$i<=$max;$i++){if(!isset($nums[$i]))$missing[]='NS/'.str_pad((string)$i,max(5,strlen((string)$max)),'0',STR_PAD_LEFT).'/'.$yr;if(count($missing)>=500)break 2;}}
require __DIR__.'/header.php'; ?><div class="form-card"><h3>Xaqiiji Document</h3><p>Ku xaqiiji REF.NS iyo/ama mobile number.</p><?php if($err):?><div class="alert"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div><label>REF.NS</label><input name="ref_no" placeholder="NS/02486/2026" value="<?=e($_POST['ref_no']??'')?>"></div><div><label>Mobile Number</label><input name="mobile" value="<?=e($_POST['mobile']??'')?>"></div></div><div class="form-actions"><button class="btn primary">Verify Document</button></div></form></div>
<?php if(is_array($result)):?><div class="form-card"><h3>Natiijada</h3><?php if(!$result):?><div class="alert">Document lama helin.</div><?php else:?><div class="success">Document waa la helay.</div><div class="table-wrap"><table><thead><tr><th>REF.NS</th><th>Magaca</th><th>Mobile</th><th>Nooca</th><th>Taariikh</th></tr></thead><tbody><?php foreach($result as $r):?><tr><td><?=e($r['ref_no'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['mobile'])?></td><td><?=e($r['document_type'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php endif;?><div class="section-heading"><div><h3>Missing Ref.NS</h3><p>Taxanaha NS/number/year ee ka maqan inta u dhexeysa refs-ka la kaydiyey; ugu badnaan 500.</p></div></div><div class="table-wrap"><table><thead><tr><th>Ref.NS maqan</th></tr></thead><tbody><?php if(!$missing):?><tr><td class="empty">Lama helin Ref.NS maqan gudaha taxanaha.</td></tr><?php else:foreach($missing as $mr):?><tr><td><?=e($mr)?></td></tr><?php endforeach;endif;?></tbody></table></div><?php require __DIR__.'/footer.php'; ?>